// Build step for the xlsx viewer (FR-43), mirroring src/lib/{cm,docx}/build-bundle.mjs.
//   node src/lib/xlsx/build-bundle.mjs
//
// SheetJS comes from @e965/xlsx, NOT npm's `xlsx` — that one is frozen at
// 0.18.5 with CVE-2023-30533 and CVE-2024-22363 unfixed, which matters for a
// viewer whose whole job is opening files it did not create. See the ADR.
import { build } from "esbuild";
import { writeFileSync } from "node:fs";

const result = await build({
  entryPoints: ["src/lib/xlsx/xlsx-entry.mjs"],
  bundle: true,
  format: "iife",
  platform: "browser",
  minify: true,
  target: "safari15",
  write: false,
});
const code = result.outputFiles[0].text;
const out = `// AUTO-GENERATED by src/lib/xlsx/build-bundle.mjs — do not edit by hand.\n/* eslint-disable */\nexport const XLSX_BUNDLE = ${JSON.stringify(code)};\n`;
writeFileSync("src/lib/xlsx/bundle.ts", out);
console.log(`wrote src/lib/xlsx/bundle.ts (${(code.length / 1024) | 0} KB minified)`);
